 for k in defaults.keys()|override.keys():
  if k in override:
   v=override[k]
   if v is None:continue
   out[k]=overlay_config(defaults[k],v) if k in defaults and type(defaults[k]) is dict and type(v) is dict else deepcopy(v)
  else:out[k]=deepcopy(defaults[k])
 return out

def overlay_config(defaults,override):
 out=dict(defaults)
 for k,v in override.items():
  if v is None:out.pop(k,None)
  elif isinstance(v,list) and isinstance(out.get(k),list):out[k]+=v
  else:out[k]=v
 return out

import copy
def coerce_rows(rows,schema):
 out=[];errors=[]
 for i,row in enumerate(rows):
  item={}
  for field,(convert,default) in schema.items():
   value=row.get(field)
   if value is None:item[field]=copy.deepcopy(default)
   else:
    try:item[field]=convert(value)
    except Exception:item[field]=copy.deepcopy(default);errors.append((i,field,value))
  out.append(item)
 return out,errors

def coerce_rows(rows,schema):
 errors=[];out=[]
 for i,row in enumerate(rows):
  item={}
  for k,(conv,default) in schema.items():
   try:item[k]=conv(row.get(k))
   except Exception:item[k]=default;errors.append((i,k,row.get(k)))
  item.update(row);out.append(item)
 return out,errors
